import {
  Component,
  ElementRef,
  Input,
  ViewChild,
  ViewEncapsulation,
  OnChanges,
  SimpleChanges,
  Injector,
  Type,
} from '@angular/core';
import { ClientMessage } from '../../types/ClientMessage';
import { MessageComponent } from '../message/message.component';
import { NgForOf } from '@angular/common';

@Component({
  selector: 'client-messages',
  encapsulation: ViewEncapsulation.None,
  imports: [MessageComponent, NgForOf],
  styleUrls: ['./messages.component.scss'],
  template: ` <div #container class="client-messages">
    <div class="client-messages__inner">
      <client-message
        *ngFor="let msg of messages; trackBy: trackByKey"
        [message]="msg"
        [partsTableComponent]="partsTableComponent"
      />
    </div>
  </div>`,
})
export class MessagesComponent implements OnChanges {
  @Input() messages: ClientMessage[] = [];
  @Input('partsTableComponent') partsTableComponent: Type<any> | null = null;

  @ViewChild('container') container!: ElementRef<HTMLDivElement>;

  private previousMessagesLength = 0;

  ngOnChanges(changes: SimpleChanges) {
    if (changes['messages']) {
      const currentMessagesLength = changes['messages'].currentValue.length;
      if (currentMessagesLength !== this.previousMessagesLength) {
        this.previousMessagesLength = currentMessagesLength;

        setTimeout(() => {
          this.scrollBottom();
        }, 250);
      }
    }
  }

  scrollBottom() {
    if (!this.container) return;
    const el = this.container.nativeElement;
    el.scrollTop = el.scrollHeight;
  }

  createInjector(message: ClientMessage) {
    return Injector.create({
      providers: [{ provide: 'message', useValue: message }],
    });
  }

  trackByKey(index: number, item: ClientMessage): string {
    return item.id;
  }
}
