import {
  Component,
  EventEmitter,
  Input,
  OnDestroy,
  OnInit,
  Output,
  ViewEncapsulation,
  Type,
  Injector,
  inject,
} from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { NgIf, NgStyle } from '@angular/common';
import {
  ConnectionStatus,
  LoraClientService,
} from '../../services/lora-client.service';
import { ClientMessageInputComponent } from '../message-input/message-input.component';
import { MessageSendComponent } from '../message-send/message-send.component';
import { MessagesComponent } from '../messages/messages.component';
import { ClientMessage } from '../../types/ClientMessage';
import { TicketInformation } from '@/lora-client/src/types/TicketInformation';

@Component({
  selector: 'lora-client',
  imports: [
    ClientMessageInputComponent,
    MessageSendComponent,
    MessagesComponent,
    NgStyle,
    NgIf,
  ],
  encapsulation: ViewEncapsulation.ShadowDom,
  styleUrls: ['./lora-client.component.scss'],
  template: `<div
    class="client__container"
    [ngStyle]="{ height: height + 'px' }"
  >
    <ng-container *ngIf="status === ConnectionStatus.CONNECTED">
      <client-messages
        class="client__messages"
        [messages]="messages"
        [partsTableComponent]="partsTableComponent"
      />

      <div class="client__input">
        <client-message-input
          class="client__input-message"
          [message]="message"
          (onMessageChanged)="onMessageChanged($event)"
          (onEnterPressed)="onEnterPressed()"
        />

        <client-message-send
          class="client__input-submit"
          (onClickSend)="sendMessage()"
        />
      </div>
    </ng-container>
    <ng-container *ngIf="status === ConnectionStatus.DISCONNECTED">
      <div class="client__status">Disconnected</div>
    </ng-container>
    <ng-container *ngIf="status === ConnectionStatus.CONNECTING">
      <div class="client__status">Connecting...</div>
    </ng-container>
    <ng-container *ngIf="status === ConnectionStatus.ERROR">
      <div class="client__status">
        <div class="client__error">
          <div class="client__error-message">
            Connection lost. Would you like to reconnect?
          </div>
          <div class="client__error-actions">
            <button (click)="onClickReconnect()">Reconnect to current session</button>
            <button (click)="onClickNewSession()">Start new session</button>
          </div>
        </div>
      </div>
    </ng-container>
    <link
      *ngIf="sanitizedStylesFile"
      rel="stylesheet"
      type="text/css"
      [href]="sanitizedStylesFile"
    />
  </div>`,
})
export class LoraClient implements OnInit, OnDestroy {
  @Input('height') height = 500;
  @Input('stylesFile') stylesFile = '';
  @Input('partsTableComponent') partsTableComponent: Type<any> | null = null;
  @Input({ required: true, alias: 'serviceUrl' }) set serviceUrl(
    value: string
  ) {
    this.loraClientService.setServiceUrl(value);
  }
  @Input({ required: true, alias: 'authHeaderSupplier' })
  set authHeaderSupplier(value: () => string) {
    this.loraClientService.setAuthHeaderSupplier(value);
  }

  @Output() onMessage: EventEmitter<ClientMessage> =
    new EventEmitter<ClientMessage>();
  @Output() onTicketCreated: EventEmitter<TicketInformation> =
    new EventEmitter<TicketInformation>();

  messages: ClientMessage[] = [];
  message: string = '';
  status = ConnectionStatus.DISCONNECTED;
  sanitizedStylesFile: SafeResourceUrl = '';

  protected readonly ConnectionStatus = ConnectionStatus;

  private loraClientService: LoraClientService = inject(LoraClientService);
  private readonly onMessageListener: OmitThisParameter<
    (message: ClientMessage) => void
  >;
  private readonly onStatusListener: OmitThisParameter<
    (status: ConnectionStatus) => void
  >;

  constructor(private sanitizer: DomSanitizer) {
    this.onMessageListener = this.onMessageReceived.bind(this);
    this.onStatusListener = this.onStatus.bind(this);
    this.loraClientService.on('message', this.onMessageListener);
    this.loraClientService.on('status', this.onStatusListener);
  }

  async ngOnInit() {
    if (this.status === ConnectionStatus.DISCONNECTED) {
      this.connect();
    }
    if (this.stylesFile) {
      this.sanitizedStylesFile = this.sanitizer.bypassSecurityTrustResourceUrl(
        this.stylesFile
      );
    }
  }

  async connect() {
    this.status = ConnectionStatus.CONNECTING;
    try {
      const sessionId =
        localStorage.getItem('LORA_CLIENT_SESSION_ID') ||
        (await this.loraClientService.createSession());

      if (!sessionId) {
        throw Error('Failed to receive session id');
      }

      await this.loraClientService.connect({ sessionId, loadHistory: false });
    } catch (e) {
      console.error('Connection error:', e);
      this.status = ConnectionStatus.ERROR;
    }
  }

  createInjector() {
    return Injector.create({
      providers: [
        { provide: 'partsTableComponent', useValue: this.partsTableComponent },
      ],
    });
  }

  sendMessage() {
    if (this.message.trim()) {
      this.loraClientService.sendMessage(this.message);
      this.message = '';
    }
  }

  onMessageChanged(message: string) {
    this.message = message;
  }

  onEnterPressed() {
    this.sendMessage();
  }

  async onClickReconnect() {
    try {
      this.status = ConnectionStatus.CONNECTING;
      await this.loraClientService.reconnect();
    } catch (e) {
      console.error('Reconnection error:', e);
      this.status = ConnectionStatus.ERROR;
    }
  }

  async onClickNewSession() {
    try {
      this.status = ConnectionStatus.CONNECTING;
      // Clear the stored session ID
      localStorage.removeItem('LORA_CLIENT_SESSION_ID');
      // Create and connect to a new session
      await this.connect();
    } catch (e) {
      console.error('New session error:', e);
      this.status = ConnectionStatus.ERROR;
    }
  }

  onMessageReceived(message: ClientMessage) {
    this.messages = this.loraClientService.getMessages();

    if (message.user !== 'me') {
      this.onMessage.emit(message);
    }

    if (
      message.widget?.widgetName === 'Ticket' &&
      message.widget.widgetProps.ticket
    ) {
      this.onTicketCreated.emit(message.widget.widgetProps.ticket);
    }
  }

  onStatus(status: ConnectionStatus) {
    this.status = status;
  }

  ngOnDestroy(): void {
    this.loraClientService.disconnect();
    this.loraClientService.off('message', this.onMessageListener);
    this.loraClientService.off('status', this.onStatusListener);
  }
}
