import {Component, inject, Inject, Input, Optional, OnInit} from '@angular/core';
import {NgForOf, NgIf} from "@angular/common";
import {LoraClientService} from "../../../services/lora-client.service";
import {EditableFieldComponent} from "./editable-field/editable-field.component";
import {ClientMessage} from '../../../types/ClientMessage';
import {KeyValue, KeyValueScalar} from '../../../types/KeyValue';
import {
  ClientTicketSuggestionWidgetMessage,
  ClientTicketWidgetMessage
} from "@/lora-client/src/types/ClientWidgetMessage";
import {TicketInformation} from "@/lora-client/src/types/TicketInformation";

@Component({
    selector: 'ticket-widget',
    imports: [NgForOf, NgIf, EditableFieldComponent],
    styleUrl: './ticket-widget.component.scss',
    template: `
    <div class="ticket-widget">
      <div class="ticket-widget__header">Ticket information:</div>
      <table class="ticket-widget__table">
        <tr *ngFor="let field of fields; trackBy: trackByFn">
          <td class="ticket-widget__field">{{ field.value }}:</td>
          <td class="ticket-widget__value">
            <editable-field
              [value]="getFieldValue(field.key)"
              [type]="editableFieldsMap.get(field.key) || 'text'"
              [isViewOnly]="!isEditable || isSaved || !editableFieldsMap.has(field.key)"
              (onChange)="setFieldValue(field.key, $event)"
            />
          </td>
        </tr>
      </table>

      <ng-container *ngIf="otherFields.length > 0">
        <div class="ticket-widget__custom-attributes">
          <div class="ticket-widget__header">Other fields:</div>
          <table class="ticket-widget__table">
            <tr *ngFor="let field of otherFields">
              <td class="ticket-widget__field">{{ field.key }}:</td>
              <td class="ticket-widget__value">
                <editable-field
                  [value]="field.value"
                  [type]="editableFieldsMap.get(field.key) || 'text'"
                  [isViewOnly]="!isEditable || isSaved || !editableFieldsMap.has(field.key)"
                  (onChange)="setFieldValue(field.key, $event)"
                />
              </td>
            </tr>
          </table>
        </div>
      </ng-container>

      <div *ngIf="!isSaved && isEditable" class="ticket-widget__actions">
        <button (click)="onClickSave()">{{ 'Save' }}</button>
      </div>
    </div>
  `
})
export class TicketWidgetComponent implements OnInit {
  private loraClientService: LoraClientService = inject(LoraClientService);
  private widget?: ClientTicketWidgetMessage | ClientTicketSuggestionWidgetMessage;

  // Input for reusable mode (when used in a loop)
  @Input() ticket?: TicketInformation;
  @Input() editable: boolean = false;

  readonly fields: KeyValue<string>[] = [
    {key: 'id', value: 'Ticket ID'},
    {key: 'title', value: 'Title'},
    {key: 'description', value: 'Description'},
    {key: 'dueDate', value: 'Due Date',},
    {key: 'geo', value: 'Geo Information'},
    {key: 'responsible', value: 'Responsible Person'},
    {key: 'completed', value: 'Completed'},
    {key: 'status', value: 'Status'}
  ];
  readonly editableFieldsMap = new Map<string, 'text' | 'date' | 'number' | 'checkbox'>([
    ['completed', 'checkbox'],
    ['responsible', 'text'],
    ['geo', 'text'],
    ['dueDate', 'date']
  ]);

  otherFields: KeyValueScalar[] = [];
  isSaved = false;
  isEditable: boolean = false;

  constructor(@Optional() @Inject('message') public message?: ClientMessage) {
    if (this.message) {
      this.widget = this.message?.widget as ClientTicketWidgetMessage | ClientTicketSuggestionWidgetMessage;
      this.isEditable = this.widget?.widgetProps.isEditable || false;
    }
  }

  ngOnInit() {
    const knownKeys = this.fields.map(({key}) => key);

    // If using input binding mode
    if (this.ticket) {
      this.isEditable = this.editable;
      this.otherFields = Object.entries(this.ticket.customData || {}).filter(([key, value]) => {
        return !knownKeys.includes(key) && typeof value !== 'object';
      }).map(([key, value]) => ({key, value})) as KeyValueScalar[];
    }
    // If using message injection mode
    else if (this.widget) {
      // Only get custom data fields, not all ticket properties
      const ticket = this.widget.widgetProps.ticket;
      this.otherFields = Object.entries(ticket?.customData || {}).filter(([key, value]) => {
        return !knownKeys.includes(key) && typeof value !== 'object';
      }).map(([key, value]) => ({key, value})) as KeyValueScalar[];
    }
  }

  onClickSave() {
    if (this.widget) {
      this.loraClientService.sendMessage(this.loraClientService.ticketToRequest(this.widget!.widgetProps.ticket), true);
      this.isSaved = true;
    }
  }

  getFieldValue(key: string): string {
    // Input mode
    if (this.ticket) {
      const value = (this.ticket as any)[key];
      if (value === undefined || value === null) return '';
      if (typeof value === 'boolean') return value ? 'Yes' : 'No';
      return String(value);
    }
    // Widget mode
    //@ts-ignore
    return this.widget?.widgetProps?.ticket?.[key] || '';
  }

  setFieldValue(key: string, value: string | number | boolean) {
    // Input mode
    if (this.ticket) {
      (this.ticket as any)[key] = value;
    }
    // Widget mode
    else if (this.widget) {
      //@ts-ignore
      this.widget.widgetProps.ticket[key] = value;
    }
  }

  trackByFn(_index: number, item: { key: string }) {
    return item.key;
  }
}
