import {
  AfterViewChecked,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation
} from '@angular/core';
import {FormsModule} from "@angular/forms";

@Component({
    selector: 'client-message-input',
    encapsulation: ViewEncapsulation.None,
    imports: [FormsModule],
    template: `<textarea
    #textarea
    [(ngModel)]="content"
    (input)="onInput()"
    (keydown)="onKeyDown($event)"
    [disabled]="disabled"
    class="client__message-input__textarea"
    placeholder="Type your message..."></textarea>`,
    styleUrls: ['./message-input.component.scss']
})
export class ClientMessageInputComponent implements OnInit, AfterViewChecked {
  @Input('message') message!: string;
  @Input('disabled') disabled: boolean = false;

  @Output() onMessageChanged: EventEmitter<string> = new EventEmitter();
  @Output() onEnterPressed: EventEmitter<void> = new EventEmitter();

  @ViewChild('textarea') textarea!: ElementRef<HTMLTextAreaElement>;
  content: string = '';

  ngOnInit() {
    this.content = this.message;
  }

  ngOnChanges(changes: SimpleChanges) {
    if (this.content !== this.message) {
      this.content = this.message;
    }
  }

  ngAfterViewChecked() {
    this.adjustTextareaHeight();
  }

  onInput() {
    this.adjustTextareaHeight();
    this.onMessageChanged.emit(this.content);
  }

  onKeyDown(event: KeyboardEvent) {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault(); // Prevent the default behavior of adding a new line

      this.onEnterPressed.emit();
    }
  }

  adjustTextareaHeight() {
    if (!this.textarea) return;

    const textarea: HTMLTextAreaElement = this.textarea.nativeElement;
    textarea.style.height = '34px'; // Reset the height
    textarea.style.height = Math.min(textarea.scrollHeight, 180) + 'px'; // Set new height, limited to 180px
  }
}
