import { Component, Inject } from '@angular/core';
import { NgForOf } from '@angular/common';
import { ClientMessage } from '../../../types/ClientMessage';
import { ClientTicketsWidgetMessage } from '@/lora-client/src/types/ClientWidgetMessage';
import { TicketInformation } from '@/lora-client/src/types/TicketInformation';
import { TicketWidgetComponent } from '../ticket-widget/ticket-widget.component';

@Component({
  selector: 'tickets-widget',
  imports: [NgForOf, TicketWidgetComponent],
  styleUrl: './tickets-widget.component.scss',
  template: `
    <div class="tickets-widget">
      <ng-container *ngFor="let ticket of tickets; trackBy: trackByFn">
        <ticket-widget [ticket]="ticket" [editable]="false"></ticket-widget>
      </ng-container>
    </div>
  `,
})
export class TicketsWidgetComponent {
  private widget?: ClientTicketsWidgetMessage;

  tickets: TicketInformation[] = [];

  constructor(@Inject('message') public message: ClientMessage) {
    this.widget = this.message?.widget as ClientTicketsWidgetMessage;
    this.tickets = this.widget?.widgetProps.tickets || [];
  }

  trackByFn(_index: number, item: { id: string }) {
    return item.id;
  }
}
