import {Component, EventEmitter, Input, Output} from '@angular/core';
import {NgIf} from "@angular/common";

@Component({
    selector: 'editable-field',
    imports: [NgIf],
    styleUrl: './editable-field.component.scss',
    template: `
    <div class="editable-field">
      <ng-container *ngIf="isViewOnly">
        <input *ngIf="isCheckbox()" type="checkbox" class="editable-field__input" [checked]="value" disabled/>
        <ng-container *ngIf="!isCheckbox()">
          {{ value }}
        </ng-container>
      </ng-container>
      <ng-container *ngIf="!isViewOnly">
        <input *ngIf="isText()" type="text" class="editable-field__input" [value]="value"
               (input)="onInputChange($event)"/>
        <input *ngIf="isNumber()" type="number" class="editable-field__input" [value]="value"
               (input)="onInputChange($event)"/>
        <input *ngIf="isCheckbox()" type="checkbox" class="editable-field__input" [checked]="value"
               (change)="onInputChange($event)"/>
        <input *ngIf="isDate()" type="date" class="editable-field__input" [value]="getFormattedDate()"
               (change)="onInputChange($event)"/>
      </ng-container>
    </div>
  `
})
export class EditableFieldComponent {
  @Input({required: true}) value: string | number | boolean = '';
  @Input({required: true}) type: 'text' | 'date' | 'number' | 'checkbox' = 'text';
  @Input({required: true}) isViewOnly: boolean = false;
  @Output() onChange = new EventEmitter<string | number | boolean>();

  isText(): boolean {
    return this.type === 'text';
  }

  isNumber(): boolean {
    return this.type === 'number';
  }

  isCheckbox(): boolean {
    return this.type === 'checkbox';
  }

  isDate(): boolean {
    return this.type === 'date';
  }


  getFormattedDate() {
    const date = new Date(this.value as string);

    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');

    const formattedDate = `${year}-${month}-${day}`;

    return formattedDate;
  }

  onInputChange(event: Event) {
    const input = event.target as HTMLInputElement;
    let newValue = input.type === 'checkbox' ? input.checked : input.value;

    if (this.isDate()) {
      const date = new Date(newValue as string);
      newValue = date.toISOString();
    }
    this.onChange.emit(newValue);
  }
}
