import {
  ClientMessage,
  ClientMessagePartDetails,
} from '../types/ClientMessage';
import ClientError from '../types/ClientError';
import { Injectable } from '@angular/core';
import { WebSocketMessage } from '../types/WebSocketMessage';
import { TicketInformation } from '@/lora-client/src/types/TicketInformation';

export enum ConnectionStatus {
  DISCONNECTED = 'disconnected',
  CONNECTED = 'connected',
  CONNECTING = 'connecting',
  RECONNECTING = 'reconnecting',
  ERROR = 'error',
}

enum MessageStatus {
  Pending,
  Sent,
}

type MessageQueueMessage = {
  id: string;
  content: any;
  status: MessageStatus;
  silent?: boolean;
};
type Events = 'message' | 'status';

interface EventListeners {
  message: (message: ClientMessage) => void;
  status: (status: ConnectionStatus) => void;
}

const HEARTBEAT_INTERVAL = 12000;

@Injectable({
  providedIn: 'root',
})
export class LoraClientService {
  private serviceUrl: string | undefined;
  //private serviceUrl = 'http://localhost:8081/api/lora';

  setServiceUrl(url: string) {
    if (!/^https?:\/\/.*/.test(url) || !url) {
      throw new ClientError('Service URL must be a valid URL, got: ' + url);
    }
    this.serviceUrl = url;
  }

  private authHeaderSupplier: (() => string) | undefined;

  setAuthHeaderSupplier(supplier: () => string) {
    this.authHeaderSupplier = supplier;
  }

  private url: string | undefined = undefined;
  private socket: WebSocket | null = null;
  private isConnected: boolean = false;
  private isError: boolean = false;
  private messages: ClientMessage[] = [];
  private messagesQueue: MessageQueueMessage[] = [];
  private listeners: { [K in Events]?: EventListeners[K][] } = {};
  private heartBeatInterval: number = 0;

  // Session tracking
  private currentSessionId: string | null = null;
  private isDeliberateDisconnect: boolean = false;

  async createSession() {
    this.checkServiceUrl();
    const options = { headers: { Authorization: this.getAuthHeader() } };
    const response = await window.fetch(`${this.serviceUrl}/session`, options);
    if (response.status !== 200) {
      throw new ClientError(
        `Failed to create session, status: ${response.status}`
      );
    }
    return response.text();
  }

  async connect(options: {
    sessionId: string;
    url?: string;
    loadHistory?: boolean;
  }) {
    this.checkServiceUrl();
    const sessionId = options.sessionId;
    this.currentSessionId = sessionId; // Store for reconnection
    this.isDeliberateDisconnect = false; // Reset flag when initiating new connection
    this.url = (options.url ?? `${this.serviceUrl}/chat/${sessionId}`)
      .replace('https://', 'wss://')
      .replace('http://', 'ws://');

    if (!sessionId) {
      throw new ClientError('Can not start connection: session id not set.');
    }
    if (!this.url) {
      throw new ClientError('Can not start connection: server url not set.');
    }
    if (this.socket && this.socket.readyState !== WebSocket.CLOSED) {
      throw new ClientError('WebSocket connection is already open or opening.');
    }

    // Clean up old socket if it exists
    if (this.socket) {
      this.socket.onopen = null;
      this.socket.onclose = null;
      this.socket.onmessage = null;
      this.socket.onerror = null;
      this.socket = null;
    }

    let oldMessages: ClientMessage[] = [];
    let resolvePromise: (value?: unknown) => void;
    let rejectPromise: (value?: any) => void = () => {};
    const promise = new Promise((resolve, reject) => {
      resolvePromise = resolve;
      rejectPromise = reject;
    });
    this.emitStatus(ConnectionStatus.CONNECTING);
    this.isError = false;
    this.isConnected = false;

    try {
      if (options.loadHistory) {
        oldMessages = await this.getMessagesHistory(sessionId);
      }

      this.socket = new WebSocket(this.url);
      this.socket.onopen = () => {
        oldMessages.forEach((message) => this.addMessage(message));

        this.isConnected = true;
        this.startHeartBeat();
        this.emitStatus(ConnectionStatus.CONNECTED);

        resolvePromise();
      };

      this.socket.onmessage = (event) => {
        const response = event.data;
        if (response === 'ping' || response === 'pong') return;

        if (typeof response === 'string') {
          this.onSocketMessage(response);
        }
      };

      this.socket.onclose = () => {
        const wasConnected = this.isConnected;
        this.isConnected = false;
        this.stopHeartBeat();

        // Reject promise if connection never succeeded
        if (!wasConnected) {
          rejectPromise?.('Connection closed before being established');
        }

        // Don't show error if it's a deliberate disconnect
        if (this.isDeliberateDisconnect) {
          this.isDeliberateDisconnect = false; // Reset flag
          this.emitStatus(ConnectionStatus.DISCONNECTED);
          return;
        }

        // Show error status - UI will display manual reconnection options
        this.isError = true;
        this.emitStatus(ConnectionStatus.ERROR);
      };

      this.socket.onerror = (event) => {
        this.isError = true;
        rejectPromise?.(event);
      };
    } catch (e) {
      console.error(e);
      this.isError = true;
      this.emitStatus(ConnectionStatus.ERROR);
      rejectPromise?.(e);
      throw e;
    }

    return promise;
  }

  async getMessagesHistory(sessionId: string): Promise<ClientMessage[]> {
    const response = await window.fetch(
      `${this.serviceUrl}/${sessionId}/messages`,
      { headers: { Authorization: this.getAuthHeader() } }
    );
    const data = await response.json();
    const messages = (data || []).map((item: any) => {
      const message: ClientMessage = {
        id: item.messageId,
        user: item.loraMessage ? 'lora' : 'me',
        content: item.text,
        time: item.creationDate,
        parts: item.parts,
        isSignal: item.isSignal || false,
      };
      return message;
    });

    return messages.reverse();
  }

  sendMessage(message: string, silent: boolean = false) {
    this.pushMessageToQueue(message, silent);
    this.processQueue();
  }

  private onSocketMessage(data: string) {
    let json = undefined;
    let content = '';
    let parts = [] as ClientMessagePartDetails[];
    let ticketSuggestionWidget = undefined;
    let ticketWidget = undefined;
    let ticketsWidget = undefined;
    let isSignal = false;
    try {
      json = JSON.parse(data) as WebSocketMessage;
      content = json.text;
      parts = json.parts;
      ticketSuggestionWidget = json.ticketSuggestionNullable;
      ticketWidget = json.createdTicketNullable;
      ticketsWidget = json.ticketSearchResultsNullable;
      isSignal = json.isSignal || false;
    } catch (e) {
      content = data;
    }
    const message: ClientMessage = {
      id: crypto.randomUUID() as string,
      user: 'lora',
      content,
      parts,
      time: Date.now(),
      isSignal,
    };

    if (
      ticketSuggestionWidget &&
      Object.keys(ticketSuggestionWidget).length > 0
    ) {
      message.widget = {
        widgetName: 'TicketSuggestion',
        widgetProps: { ticket: ticketSuggestionWidget, isEditable: true },
      };
    } else if (ticketWidget && Object.keys(ticketWidget).length > 0) {
      message.widget = {
        widgetName: 'Ticket',
        widgetProps: { ticket: ticketWidget, isEditable: false },
      };
    } else if (ticketsWidget) {
      message.widget = {
        widgetName: 'Tickets',
        widgetProps: { tickets: ticketsWidget },
      };
    }

    this.addMessage(message);
  }

  private processQueue() {
    const message = this.messagesQueue.pop();
    if (!message) return;

    if (!message.silent) {
      this.addMessage({
        id: crypto.randomUUID() as string,
        user: 'me',
        time: Date.now(),
        content: message.content,
        isSignal: false,
      });
    }
    this.socket?.send(message?.content);
    message.status = MessageStatus.Sent;
  }

  private pushMessageToQueue(message: string, silent = false) {
    const id = crypto.randomUUID();

    this.messagesQueue.push({
      id,
      silent,
      content: message,
      status: MessageStatus.Pending,
    });
  }

  private addMessage(message: ClientMessage) {
    this.messages.push(message);

    this.emitMessage(message);
  }

  private emitMessage(message: ClientMessage) {
    this.listeners.message?.forEach((listener) => {
      try {
        listener(message);
      } catch (e) {
        console.error(e);
      }
    });
  }

  private emitStatus(status: ConnectionStatus) {
    this.listeners.status?.forEach((listener) => {
      try {
        listener(status);
      } catch (e) {
        console.error(e);
      }
    });
  }

  on<T extends Events>(event: T, listener: EventListeners[T]) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    (this.listeners[event] as any[]).push(listener);
  }

  off<K extends Events>(event: K, listener: EventListeners[K]) {
    const data = this.listeners[event] as any[];
    const index = data.indexOf(listener);

    if (index >= 0) {
      (this.listeners[event] as []).splice(index, 1);
    }
  }

  getMessages() {
    return [...this.messages];
  }

  disconnect() {
    this.messages = [];
    this.messagesQueue = [];
    this.isDeliberateDisconnect = true;
    if (this.socket) {
      this.socket.close(1000, 'Closed by client');
    }
  }

  /**
   * Manually reconnect to the current session
   * @returns Promise that resolves when reconnected
   */
  async reconnect(): Promise<void> {
    if (!this.currentSessionId) {
      throw new ClientError('No session ID available for reconnection');
    }

    this.isError = false;
    await this.connect({
      sessionId: this.currentSessionId,
      loadHistory: false,
    });
  }

  /**
   * Get the current session ID
   * @returns The current session ID or null if no session is active
   */
  getCurrentSessionId(): string | null {
    return this.currentSessionId;
  }

  private sendHeartBeat() {
    if (this.isConnected) {
      this.socket?.send('ping');
    }
  }

  private startHeartBeat() {
    this.heartBeatInterval = window.setInterval(() => {
      this.sendHeartBeat();
    }, HEARTBEAT_INTERVAL);
  }

  private stopHeartBeat() {
    window.clearInterval(this.heartBeatInterval);
  }

  ticketToRequest(ticket: TicketInformation) {
    return (
      'This ticket looks good please save it now: ' + JSON.stringify(ticket)
    );
  }

  private checkServiceUrl() {
    if (!this.serviceUrl) {
      throw new ClientError('Service URL is not set.');
    }
  }

  private getAuthHeader() {
    return this.authHeaderSupplier?.() ?? '';
  }
}
